// ✓ Flatten: verified type-identical to the original
/* @scripttype preserveParamNames */
export function Flatten(Schemas): any {
  const m1 = matches<readonly [ Hole<"Head">, ...Hole<"Tail"> ]>(Schemas)
  if (m1) {
    const m2 = matches<Union<Hole<"Inner">>>(m1.Head)
    if (m2) {
      return [...Flatten(m2.Inner), ...Flatten(m1.Tail)]
    }
    return [m1.Head, ...Flatten(m1.Tail)]
  }
  return []
}
